import java.util.*;

class NaiveSubtree {
    private final List<List<Integer>> adj;
    private final long[] val;

    NaiveSubtree(int n, int[][] edges, long[] values) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        val = values.clone();
    }

    void update(int node, long v) {
        val[node] = v;                  // O(1)
    }

    long subtreeSum(int node, int parent) {   // O(n)
        long sum = val[node];
        for (int child : adj.get(node)) {
            if (child != parent) sum += subtreeSum(child, node);
        }
        return sum;
    }
}

