import java.util.*;

class EulerTourSubtree {
    private final int n;
    private final int[] tin, tout;
    private final long[] bit;   // Fenwick tree over the flattened array (1-based)

    EulerTourSubtree(int n, int root, int[][] edges, long[] values) {
        this.n = n;
        tin = new int[n];
        tout = new int[n];
        bit = new long[n + 1];
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }

        // Iterative DFS to compute tin/tout (chain-safe).
        int[] parent = new int[n];
        int timer = 0;
        Deque<int[]> stack = new ArrayDeque<>();   // {node, childIndex}
        parent[root] = root;
        stack.push(new int[]{root, 0});
        tin[root] = timer++;
        while (!stack.isEmpty()) {
            int[] top = stack.peek();
            int node = top[0];
            if (top[1] < adj.get(node).size()) {
                int next = adj.get(node).get(top[1]++);
                if (next != parent[node]) {
                    parent[next] = node;
                    tin[next] = timer++;
                    stack.push(new int[]{next, 0});
                }
            } else {
                tout[node] = timer - 1;   // last index in this subtree
                stack.pop();
            }
        }
        // Load values at their tin positions.
        for (int v = 0; v < n; v++) bitUpdate(tin[v] + 1, values[v]);
    }

    private void bitUpdate(int i, long delta) {
        for (; i <= n; i += i & -i) bit[i] += delta;
    }

    private long bitPrefix(int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    }

    void update(int node, long newVal) {
        long old = subtreeSumRange(tin[node], tin[node]);
        bitUpdate(tin[node] + 1, newVal - old);   // add the delta
    }

    private long subtreeSumRange(int l, int r) {  // r inclusive, 0-based tin range
        return bitPrefix(r + 1) - bitPrefix(l);
    }

    long subtreeSum(int node) {
        return subtreeSumRange(tin[node], tout[node]);
    }
}

