import sys
from collections import defaultdict

class EulerTourSubtree:
    def __init__(self, n: int, root: int, edges: list[tuple[int, int]], values: list[int]) -> None:
        self.n = n
        self.tin = [0] * n
        self.tout = [0] * n
        self.bit = [0] * (n + 1)   # Fenwick over flattened array, 1-based
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Iterative DFS for tin/tout (chain-safe).
        parent = [root] * n
        timer = 0
        self.tin[root] = timer
        timer += 1
        stack = [(root, iter(adj[root]))]
        while stack:
            node, it = stack[-1]
            advanced = False
            for nxt in it:
                if nxt != parent[node]:
                    parent[nxt] = node
                    self.tin[nxt] = timer
                    timer += 1
                    stack.append((nxt, iter(adj[nxt])))
                    advanced = True
                    break
            if not advanced:
                self.tout[node] = timer - 1   # last index in this subtree
                stack.pop()

        for v in range(n):
            self._bit_update(self.tin[v] + 1, values[v])

    def _bit_update(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def _bit_prefix(self, i: int) -> int:
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def _range(self, l: int, r: int) -> int:    # inclusive 0-based tin range
        return self._bit_prefix(r + 1) - self._bit_prefix(l)

    def update(self, node: int, new_val: int) -> None:
        old = self._range(self.tin[node], self.tin[node])
        self._bit_update(self.tin[node] + 1, new_val - old)

    def subtree_sum(self, node: int) -> int:
        return self._range(self.tin[node], self.tout[node])

